package dev.exodus.teleporter.domain;import dev.exodus.domain.Association;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;class BossBarAudiencePolicyTest{@Test void allAssociatedOnlineRolesSeeBarButUnrelatedPlayersDoNot(){assertTrue(BossBarAudiencePolicy.visible(Association.MATCH_PLAYER,true));assertTrue(BossBarAudiencePolicy.visible(Association.INITIAL_SPECTATOR,true));assertTrue(BossBarAudiencePolicy.visible(Association.AUTO_SPECTATOR,true));assertFalse(BossBarAudiencePolicy.visible(null,true));assertFalse(BossBarAudiencePolicy.visible(Association.MATCH_PLAYER,false));}}
